update_rule.pseudocode:
E_active <- sample_fraction_of_edges(signals.graph, fraction=daily_contact_fraction)
# Add exogenous random contacts
for each agent i:
  k ~ Poisson(exogenous_contact_rate)
  for t in 1..k:
    j <- sample_uniform_agent(excluding=i)
    if RNG.uniform() < meeting_noise:
      add_edge(E_active, (i,j))
signals.daily_active_edges <- E_active
